   135  /*************************************************************************
   136  // PackHeader
   137  //
   138  // We try to be able to unpack UPX 0.7x (versions 8 & 9) and at
   139  // least to detect older versions, so this is a little bit messy.
   140  **************************************************************************/
   141
   142  PackHeader::PackHeader() noexcept { reset(); }
   143
   144  void PackHeader::reset() noexcept {
   145      mem_clear(this);
   146      version = -1;
   147      format = -1;
   148      compress_result.reset();
   149  }
