   151  /*************************************************************************
   152  // extremely simple checksum for the header itself (since version 10)
   153  **************************************************************************/
   154
   155  static byte get_packheader_checksum(SPAN_S(const byte) buf, int blen) {
   156      assert(blen >= 4);
   157      assert(get_le32(buf) == UPX_MAGIC_LE32);
   158      buf += 4;
   159      blen -= 4;
   160      unsigned c = 0;
   161      while (blen-- > 0)
   162          c += *buf++;
   163      c %= 251;
   164      return (byte) c;
   165  }
